-- Map only unambiguous Spotify IDs to canonical utwu_id.
UPDATE playlist_item AS p
SET utwu_id = (
    SELECT m.utwu_id
    FROM middle_end AS m
    WHERE m.spotify_id = p.external_track_id
)
WHERE p.external_track_id IS NOT NULL
  AND (
      SELECT COUNT(*)
      FROM middle_end AS m
      WHERE m.spotify_id = p.external_track_id
  ) = 1;
COMMIT;

